INSERT INTO `achievement` (`Description`, `Title`, `Reward`, `ID`, `InstanceID`, `Faction`, `Supercedes`, `Category`, `MinimumCriteria`, `Points`, `Flags`, `UiOrder`, `IconFileID`, `RewardItemID`, `CriteriaTree`, `SharesCriteria`, `CovenantID`, `HiddenBeforeDisplaySeason`, `LegacyAfterTimeEvent`, `VerifiedBuild`) VALUES
('Earn 5 Motes of Omnial Inquiry to use in the Omnium Folio.', 'Omnium Folio Studies', 'Decor Reward: Sunstrider Omnium Simulacrum', 63325, -1, -1, 0, 15610, 0, 10, 132096, 49, 7549225, 0, 229349, 0, 0, 0, 0, 68974),
('Dissipate 5 Storms in Val.', 'Climate Strange: Val', 'Pet Reward: Unlock Fishstick Keith for purchase', 62903, -1, -1, 0, 15610, 0, 5, 131072, 28, 135833, 0, 227629, 0, 0, 0, 0, 68974),
('Score a goal with the Kickable Practice Ball in Silvermoon while wearing a Tabard of Participation.', 'Goal!', 'Decor Reward: Prized Orb of Azeroth, Framed Horde Pride and Framed Alliance Pride', 63343, -1, -1, 0, 15268, 0, 0, 131072, 121, 660531, 0, 229492, 0, 0, 0, 0, 68974),
('Honor the flames of Midnight.', 'Flame Warden of Midnight', '', 61336, -1, 1, 0, 161, 0, 10, 131072, 16, 135265, 0, 216911, 0, 0, 0, 0, 68974),
('Honor the flames of Midnight.', 'Flame Keeper of Midnight', '', 61335, -1, 0, 0, 161, 0, 10, 131072, 37, 135265, 0, 216905, 0, 0, 0, 0, 68974),
('Defeat the Lightblinded Vanguard while your entire raid has Maximum Aura in The Voidspire on Normal difficulty or higher.', 'Aura Farming', '', 61936, 2912, -1, 0, 15566, 0, 10, 0, 26, 135872, 0, 221315, 0, 0, 0, 0, 68974),
('Defeat Vaelgor & Ezzorak after all players break each Nullzone\'s tethers within 3 seconds in The Voidspire on Normal difficulty or higher.', 'Ready, Set, Snap!', '', 61911, 2912, -1, 0, 15566, 0, 10, 0, 25, 615099, 0, 221094, 0, 0, 0, 0, 68974),
('Defeat Fallen-King Salhadaar after everyone /kneels to him before the battle starts in The Voidspire on Normal difficulty or higher.', 'It\'s Treason Then', '', 61514, 2912, -1, 0, 15566, 0, 10, 0, 24, 7137559, 0, 219335, 0, 0, 0, 0, 68974),
('Defeat Belo\'ren, Child of Al\'ar after infusing the Sunwell Egg with Light and Void magic in March on Quel\'Danas on Normal difficulty or higher.', 'Eggsistential Crisis', '', 61381, -1, -1, 0, 15566, 0, 10, 0, 29, 135980, 0, 217673, 0, 0, 0, 0, 68974),
('Defeat Crown of the Cosmos after slaying a Fleshy Monstrosity and returning all of its meat to The Emptiness in The Voidspire on Normal difficulty or higher.', 'We Will, In Fact, See It Again', '', 61346, 2912, -1, 0, 15566, 0, 10, 0, 27, 801291, 0, 217552, 0, 0, 0, 0, 68974),
('Defeat Midnight Falls in March on Quel\'Danas on Mythic difficulty while in a guild group.', 'Mythic: Midnight Falls Guild Run', '', 61611, 2913, -1, 0, 15570, 0, 10, 61440, 9, 7448204, 0, 219711, 0, 0, 0, 0, 68974),
('Complete the raid achievements listed below.', 'Glory of the Midnight Raider', 'Mount: Tenebrous Harrower', 61380, -1, -1, 0, 168, 0, 25, 143360, 68, 7454100, 260887, 217671, 0, 0, 0, 0, 68974),
('Complete the following achievements:', 'A Trip Through the Stars', 'Reward: Unlock the Netherforged Nullframe for purchase', 62874, -1, -1, 0, 15610, 0, 15, 196608, 20, 7535090, 0, 229650, 0, 0, 0, 0, 68974);
