INSERT INTO `mount` (`Name`, `SourceText`, `Description`, `ID`, `MountTypeID`, `Flags`, `SourceTypeEnum`, `SourceSpellID`, `PlayerConditionID`, `MountFlyRideHeight`, `UiModelSceneID`, `MountSpecialRiderAnimKitID`, `MountSpecialSpellVisualKitID`, `VerifiedBuild`) VALUES
('Tortured Gorger', '|cFFFFD200Zones:|r Val and Naigtal |n|cFFFFD200Achievement:|r Heroic Showdowns|n|cFFFFD200Vendor:|r Kifaan|n|cFFFFD200Cost: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Both domanaar and ethereals have tried to cage this devourer. Each time they have failed. Now, soaked in the energies of the void, this tormented gorger is ready to unleash havoc.', 3033, 230, 0, 5, 1297427, 0, 0, 45, 0, 0, 68974),
('Netherforged Nullframe', '|cFFFFD200Achievement:|r A Trip Through the Stars|n|cFFFFD200Zone:|r Naigtal|n|cFFFFD200Vendor:|r Kifaan|n|cFFFFD200Cost: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Assembled by the Lightforged, sundered by the Hal\'hadar, and restored by a Technomancer. A matrix of light, void, and arcane swirls within this renewed Warframe.', 2990, 424, 0, 5, 1294663, 0, 0, 4, 0, 0, 68974),
('Voidmancer\'s Starcarver', '|cFFFFD200Achievement:|r A Trip Around the Stars|n|cFFFFD200Zone:|r Val|n|cFFFFD200Vendor:|r Kifaan|n|cFFFFD200Cost: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'This pinnacle of Voidmancer transport technology was once a symbol of status and power among high ranking domanaar. After its creator mysteriously vanished, it was viewed as unseemly when used on core worlds gatherings.', 2988, 437, 0, 5, 1294648, 0, 0, 4, 0, 0, 68974),
('Bilgewater X-TREME Firework Rocket', '|cFFFFD200Trading Post|r', 'The engineers of Undermine were so preoccupied with whether or not they COULD make a faster rocket, they didn\'t stop to think if they should.', 2975, 424, 192, 11, 1292344, 0, 0, 4, 0, 0, 68974);
